#![cfg(feature = "decision-d3")]

//! d3-edge and d3-nano against the Hugging Face reference fixtures (transformers 5.17.0,
//! `fixtures/d3-*.json`, generated by `tools/generate_d3_reference.py`).
//!
//! AUDIOGRAPH_MODELS_DIR must hold `d3-edge/` and `d3-nano/` (the model manager's layout);
//! AUDIOGRAPH_D3_EP selects `cpu` (default), `cuda` or `metal`.

use audio_graph_decision_engine::{
    Answer, DecisionEngine, DecisionRequest, EngineConfig, ExecutionProvider,
    d3::{CHECKPOINTS, D3Engine, Precision},
};
use serde_json::Value;

/// FP32 target per probability against the reference's FP32 run.
const FP32_TOLERANCE: f64 = 1e-3;
/// The BF16 reference moves by up to 3.4e-2 between its own batch sizes; BF16 must stay inside that
/// and keep every pick whose FP32 top-two margin is wider than it.
const BF16_TOLERANCE: f64 = 5e-2;
const BF16_PICK_MARGIN: f64 = 0.05;

fn provider() -> ExecutionProvider {
    match std::env::var("AUDIOGRAPH_D3_EP").as_deref() {
        Ok("cuda") => ExecutionProvider::Cuda,
        Ok("metal") => ExecutionProvider::CoreMl,
        _ => ExecutionProvider::Cpu,
    }
}

/// The option probabilities of an answer, after checking the native confidence semantics: `confidence`
/// is the probability of the reported answer, and noul's map agrees with `noul`.
fn vector(answer: &Answer) -> Vec<f64> {
    let max = |p: &[f64]| p.iter().copied().fold(0.0, f64::max);
    match answer {
        Answer::Choice {
            choice,
            probabilities,
            confidence,
        } => {
            assert_eq!(*confidence, probabilities[choice]);
            assert_eq!(
                *confidence,
                max(&probabilities.values().copied().collect::<Vec<_>>())
            );
            probabilities.values().copied().collect()
        }
        Answer::Noul {
            noul,
            probabilities,
            confidence,
        } => {
            let probabilities = probabilities.as_ref().expect("noul probabilities");
            assert_eq!(*noul, probabilities["true"]);
            assert_eq!(
                confidence.expect("noul confidence"),
                noul.max(probabilities["false"])
            );
            vec![probabilities["false"], *noul]
        }
        Answer::Score {
            probabilities,
            confidence,
            ..
        } => {
            assert_eq!(*confidence, max(probabilities));
            probabilities.clone()
        }
    }
}

fn floats(v: &Value) -> Vec<f64> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_f64().unwrap())
        .collect()
}

fn argmax(p: &[f64]) -> usize {
    (1..p.len()).fold(0, |best, i| if p[i] > p[best] { i } else { best })
}

fn margin(p: &[f64]) -> f64 {
    let mut sorted = p.to_vec();
    sorted.sort_by(|a, b| b.total_cmp(a));
    sorted[0] - sorted.get(1).copied().unwrap_or(0.0)
}

async fn check(id: &str, fixture: &str, precision: Precision) {
    let root = std::env::var_os("AUDIOGRAPH_MODELS_DIR")
        .expect("set AUDIOGRAPH_MODELS_DIR to the app-data models directory");
    let mut config = EngineConfig::new(root.into());
    config.execution_provider = provider();
    let checkpoint = CHECKPOINTS.iter().find(|c| c.id == id).unwrap();
    let engine = D3Engine::load(&config, checkpoint)
        .unwrap()
        .with_precision(precision);
    let fixture: Value = serde_json::from_str(fixture).unwrap();
    let (mut questions, mut worst) = (0, 0f64);
    for case in fixture["cases"].as_array().unwrap() {
        // Cases with JSON instructions/descriptions or no instructions are outside the typed contract.
        let Ok(request) = serde_json::from_value::<DecisionRequest>(case["request"].clone()) else {
            continue;
        };
        let response = engine.system_one(&request).await.unwrap();
        assert_eq!(response.engine_id, id);
        let expected_tokens: u64 = case["questions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|q| q["input_ids"].as_array().unwrap().len() as u64)
            .sum();
        assert_eq!(
            response.usage.input_tokens, expected_tokens,
            "{id}/{}",
            case["id"]
        );
        for q in case["questions"].as_array().unwrap() {
            let qid = q["id"].as_str().unwrap();
            let got = vector(&response.answers[qid]);
            let (fp32, official) = (floats(&q["fp32"]), floats(&q["official"]));
            let diff = got
                .iter()
                .zip(&fp32)
                .map(|(a, b)| (a - b).abs())
                .fold(0.0, f64::max);
            worst = worst.max(diff);
            questions += 1;
            match precision {
                Precision::F32 => {
                    assert!(
                        diff <= FP32_TOLERANCE,
                        "{id}/{qid}: |p - p_fp32| = {diff:e}"
                    );
                    assert_eq!(argmax(&got), argmax(&official), "{id}/{qid}: pick");
                }
                Precision::Bf16 => {
                    assert!(
                        diff <= BF16_TOLERANCE,
                        "{id}/{qid}: |p - p_fp32| = {diff:e}"
                    );
                    if margin(&fp32) > BF16_PICK_MARGIN {
                        assert_eq!(argmax(&got), argmax(&official), "{id}/{qid}: pick");
                    }
                }
            }
        }
    }
    println!(
        "{id} {precision:?} on {:?}: {questions} questions, max |p - p_fp32| = {worst:.3e}",
        provider()
    );
    assert!(questions >= 20);
}

#[tokio::test]
#[ignore = "requires AUDIOGRAPH_MODELS_DIR with d3-edge/"]
async fn d3_edge_matches_the_reference() {
    check(
        "d3-edge",
        include_str!("../fixtures/d3-edge.json"),
        Precision::F32,
    )
    .await;
    if provider() != ExecutionProvider::Cpu {
        check(
            "d3-edge",
            include_str!("../fixtures/d3-edge.json"),
            Precision::Bf16,
        )
        .await;
    }
}

